def beniget_extract(repo_path: str, buggy_file: str, buggy_function: str) -> dict:
    import ast
    try:
        import beniget
    except ImportError:
        return {"call_graph": [], "dataflow_paths": []}

    resolved = resolve_file_in_repo(repo_path, buggy_file)
    if resolved:
        buggy_file = resolved
    target_path = os.path.join(repo_path, buggy_file)
    if not os.path.exists(target_path):
        return {"call_graph": [], "dataflow_paths": []}

    try:
        with open(target_path) as f:
            source = f.read()
        tree = ast.parse(source, filename=target_path)
    except (SyntaxError, UnicodeDecodeError):
        return {"call_graph": [], "dataflow_paths": []}

    try:
        duc = beniget.DefUseChains()
        duc.visit(tree)
    except Exception:
        return {"call_graph": [], "dataflow_paths": []}

    # BugFix: detect whether buggy_function is a ClassDef or FunctionDef
    is_class = any(
        isinstance(node, ast.ClassDef) and node.name == buggy_function
        for node in ast.walk(tree)
    )

    call_graph = []
    for node, chain in duc.chains.items():
        # BugFix: added ast.ClassDef — previously classes were silently skipped
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            if node.name == buggy_function:
                for user in chain.users():
                    if isinstance(user.node, ast.Call):
                        call_graph.append({
                            "target_func": node.name,
                            "hop_distance": 1,
                            "direction": "callee",
                            "file_path": buggy_file,
                            "start_line": getattr(user.node, "lineno", 0),
                            "end_line": getattr(user.node, "end_lineno", 0),
                        })

    # BugFix: for ClassDef, also search cross-file references (inheritance, instantiation, method calls)
    if is_class:
        all_py = collect_py_files(repo_path)
        seen_files = set()
        for py_rel in all_py:
            if py_rel == buggy_file:
                continue
            full_path = os.path.join(repo_path, py_rel)
            refs = _search_class_refs_in_file(full_path, buggy_function)
            for ref in refs:
                ref["file_path"] = py_rel
                call_graph.append(ref)
                seen_files.add(py_rel)
        if seen_files:
            log.info("[beniget] ClassDef '%s': found refs in %d cross-files", buggy_function, len(seen_files))

    return {"call_graph": call_graph, "dataflow_paths": []}


# ---------------------------------------------------------------------------
